mapper.select:
SELECT T.RNUM,T.USER_NO, T.USER_NM , T.ENABLED, T.USER_CODE, T.USER_STATUS, T.USER_CREATE , T.USER_PHONE, T.USER_MAIL, T.USER_INDATE , CASE WHEN T.DEPT_NO IS NOT NULL THEN '본사' ELSE '기타' END AS 소속 , T.DEPT_NM AS DEPT_NM, T.POSITION_NM AS POSITION_NM, T.AUTH_NAME AS AUTH_NAME, T.AUTH_DATE AS AUTH_DATE FROM ( SELECT ROW_NUMBER() OVER (ORDER BY U.USER_CREATE DESC) AS RNUM , U.USER_NO, U.USER_NM, U.ENABLED, U.USER_CODE, U.USER_STATUS, U.USER_CREATE , U.USER_PHONE, U.USER_MAIL, U.USER_INDATE , E.DEPT_NO, D.DEPT_NM, P.POSITION_NM , A.AUTH_NAME, A.AUTH_DATE FROM TB_USER U LEFT JOIN AUTH A ON U.USER_NO = A.USER_NO LEFT JOIN EMPLOYEE E ON U.USER_NO = E.USER_NO LEFT JOIN DEPT D ON E.DEPT_NO = D.DEPT_NO LEFT JOIN POSITION P ON E.POSITION_NO = P.POSITION_NO WHERE 1=1 AND E.USER_NO IS NOT NULL AND U.USER_CODE NOT IN (2, 4)
AND ( U.USER_NO LIKE '%' || #{keyword} || '%' OR U.USER_NM LIKE '%' || #{keyword} || '%' OR D.DEPT_NM LIKE '%' || #{keyword} || '%' OR P.POSITION_NM LIKE '%' || #{keyword} || '%' OR A.AUTH_DATE LIKE '%' || #{keyword} || '%' OR U.ENABLED LIKE '%' || #{keyword} || '%' OR (CASE WHEN U.ENABLED = 1 THEN '인증' WHEN U.ENABLED = 0 THEN '미인증' END) LIKE '%' || #{keyword} || '%' OR (CASE WHEN U.USER_CODE IN (1, 3) THEN '본사' ELSE '기타' END) LIKE '%' || #{keyword} || '%' OR U.USER_STATUS LIKE '%' || #{keyword} || '%' OR (CASE WHEN U.USER_STATUS = 1 THEN '정상' WHEN U.USER_STATUS = 2 THEN '탈퇴' END) LIKE '%' || #{keyword} || '%'
)
AND U.USER_CODE IN (1, 3)
AND U.USER_CODE IN (2, 4)
AND D.DEPT_NM = #{subCategory}
AND P.POSITION_NM = #{subCategory}
AND U.ENABLED = 1
AND U.ENABLED = 0
) T WHERE T.RNUM BETWEEN (#{currentPage} - 1) * 10 + 1 AND #{currentPage} * 10 ORDER BY T.USER_CREATE DESC, T.USER_NO ASC

SELECT T.RNUM,T.USER_NO, T.USER_NM , T.ENABLED, T.USER_CODE, T.USER_STATUS, T.USER_CREATE , T.USER_PHONE, T.USER_MAIL, T.USER_INDATE , CASE WHEN T.DEPT_NO IS NOT NULL THEN '본사' WHEN T.STORE_NM IS NOT NULL THEN '가맹점' ELSE '기타' END AS 소속 , T.DEPT_NM AS DEPT_NM, T.STORE_NM AS STORE_NM, T.POSITION_NM AS POSITION_NM, T.AUTH_NAME AS AUTH_NAME, T.AUTH_DATE AS AUTH_DATE FROM ( SELECT ROW_NUMBER() OVER (ORDER BY U.USER_CREATE DESC) AS RNUM , U.USER_NO, U.USER_NM, U.ENABLED, U.USER_CODE, U.USER_STATUS, U.USER_CREATE , U.USER_PHONE, U.USER_MAIL, U.USER_INDATE , E.DEPT_NO, SE.STORE_NM, D.DEPT_NM, P.POSITION_NM , A.AUTH_NAME, A.AUTH_DATE FROM TB_USER U LEFT JOIN AUTH A ON U.USER_NO = A.USER_NO LEFT JOIN EMPLOYEE E ON U.USER_NO = E.USER_NO LEFT JOIN STORE_EMP SE ON U.USER_NO = SE.USER_NO LEFT JOIN DEPT D ON E.DEPT_NO = D.DEPT_NO LEFT JOIN POSITION P ON E.POSITION_NO = P.POSITION_NO OR SE.POSITION_NO = P.POSITION_NO WHERE 1=1
AND ( U.USER_NO LIKE '%' || #{keyword} || '%' OR U.USER_NM LIKE '%' || #{keyword} || '%' OR D.DEPT_NM LIKE '%' || #{keyword} || '%' OR P.POSITION_NM LIKE '%' || #{keyword} || '%' OR A.AUTH_DATE LIKE '%' || #{keyword} || '%' OR SE.STORE_NM LIKE '%' || #{keyword} || '%' OR U.ENABLED LIKE '%' || #{keyword} || '%' OR (CASE WHEN U.ENABLED = 1 THEN '인증' WHEN U.ENABLED = 0 THEN '미인증' END) LIKE '%' || #{keyword} || '%' OR (CASE WHEN U.USER_CODE IN (1, 3) THEN '본사' WHEN U.USER_CODE IN (2, 4) THEN '가맹점' ELSE '기타' END) LIKE '%' || #{keyword} || '%' OR U.USER_STATUS LIKE '%' || #{keyword} || '%' OR (CASE WHEN U.USER_STATUS = 1 THEN '정상' WHEN U.USER_STATUS = 2 THEN '탈퇴' END) LIKE '%' || #{keyword} || '%'
)
AND U.USER_CODE IN (1, 3)
AND U.USER_CODE IN (2, 4)
AND D.DEPT_NM = #{subCategory}
AND P.POSITION_NM = #{subCategory}
AND U.ENABLED = 1
AND U.ENABLED = 0
) T WHERE T.RNUM BETWEEN (#{currentPage} - 1) * 10 + 1 AND #{currentPage} * 10 ORDER BY T.USER_CREATE DESC, T.USER_NO ASC

mapper.update:
UPDATE AUTH
SET AUTH_NAME = #{authName}
WHERE USER_NO = #{userNo}

UPDATE TB_USER
SET ENABLED = #{enabled}
WHERE USER_NO = #{userNo}

