SELECT COUNT(*) FROM TB_USER U LEFT JOIN EMPLOYEE E ON U.USER_NO = E.USER_NO LEFT JOIN DEPT D ON E.DEPT_NO = D.DEPT_NO LEFT JOIN POSITION P ON E.POSITION_NO = P.POSITION_NO LEFT JOIN STORE_EMP SE ON U.USER_NO = SE.USER_NO LEFT JOIN AUTH A ON U.USER_NO = A.USER_NO WHERE 1 = 1
AND ( U.USER_NO LIKE '%' || #{keyword} || '%' OR U.USER_NM LIKE '%' || #{keyword} || '%' OR D.DEPT_NM LIKE '%' || #{keyword} || '%' OR P.POSITION_NM LIKE '%' || #{keyword} || '%' OR A.AUTH_DATE LIKE '%' || #{keyword} || '%' OR SE.STORE_NM LIKE '%' || #{keyword} || '%' OR U.ENABLED LIKE '%' || #{keyword} || '%' OR (CASE WHEN U.USER_CODE IN (1, 3) THEN '본사' WHEN U.USER_CODE IN (2, 4) THEN '가맹점' ELSE '기타' END) LIKE '%' || #{keyword} || '%' )
AND U.USER_CODE IN (1, 3)
AND U.USER_CODE IN (2, 4)
AND D.DEPT_NM = #{subCategory}
AND P.POSITION_NM = #{subCategory}
